<?php
require_once __DIR__.'/includes/bootstrap.php';$pdo=sv_next_db();$elections=sv_public_elections($pdo);$id=int_input('election_id',(int)($elections[0]['id']??0));$chosen=null;foreach($elections as $e)if((int)$e['id']===$id)$chosen=$e;
if($id&&!$chosen)sv_error_page(404,'Election unavailable','Choose a published election.',[]);
$page=max(1,int_input('page',1));$offset=min($page-1,100000)*30;$s=$pdo->prepare('SELECT summary,created_at FROM election_changes WHERE election_id=? ORDER BY created_at DESC,id DESC LIMIT 31 OFFSET '.$offset);$s->execute([$id]);$rows=$s->fetchAll();$more=count($rows)>30;$rows=array_slice($rows,0,30);
$pageTitle='Election change history';$activeNav='guide.php';require __DIR__.'/includes/header.php';
?>
<div class="feature-page stack"><h1 class="visually-hidden">Election change history</h1><p>Changes recorded after this feature was enabled. Older edits are not reconstructed.</p><form method="get" class="feature-toolbar"><label for="changes-election">Election</label><select id="changes-election" class="input" name="election_id"><?php foreach($elections as $e): ?><option value="<?= (int)$e['id'] ?>" <?= (int)$e['id']===$id?'selected':'' ?>><?= e($e['title']) ?></option><?php endforeach; ?></select><button class="btn btn--secondary">Choose election</button></form><?php if(!$rows): ?><div class="feature-empty"><h2>No changes recorded yet</h2><p>Future updates to this election’s schedule and candidate information will appear here.</p></div><?php endif; ?><ol class="change-history"><?php foreach($rows as $row): ?><li><time datetime="<?= e(to_datetime($row['created_at'])->format(DATE_ATOM)) ?>"><?= e(fmt_datetime($row['created_at'])) ?></time><p><?= e($row['summary']) ?></p></li><?php endforeach; ?></ol><div class="row"><?php if($page>1): ?><a class="link" href="<?= e(url('changes.php?election_id='.$id.'&page='.($page-1))) ?>">Newer changes</a><?php endif; ?><?php if($more): ?><a class="link" href="<?= e(url('changes.php?election_id='.$id.'&page='.($page+1))) ?>">Older changes</a><?php endif; ?></div><a class="link" href="<?= e(url('guide.php?election_id='.$id)) ?>">Back to election guide</a></div>
<?php require __DIR__.'/includes/footer.php'; ?>
